describe('evaluateAgentState', () => {
  const evaluateMock = vi.mocked(evaluate);

  beforeEach(() => {
    evaluateMock.mockReset();
  });

  it('retains legacy error constructors and normalization as aliases', () => {
    expect(JevEvaluationError).toBe(EvaluationError);
    expect(JevHttpError).toBe(EvaluationHttpError);
    expect(normalizeJevEvaluationError).toBe(normalizeEvaluationError);
  });

  it('validates string model overrides before invoking a transport', async () => {
    await expect(evaluateAgentState(state, 'jev-latest')).rejects.toThrow('ROUTER_MODEL must be');
    expect(evaluateMock).not.toHaveBeenCalled();
  });

  it('rejects SDK overrides outside the Gateway transport before a request', () => {
    const model = { specificationVersion: 'v1' } as never;
    expect(() => createEvaluator({ provider: 'typesafe', model: 'jev-latest', apiKey: 'key' }, model))
      .toThrow('requires ROUTER_PROVIDER=vercel');
    expect(evaluateMock).not.toHaveBeenCalled();
  });

  it('passes a bounded request policy and normalizes valid confidence metadata', async () => {
    evaluateMock.mockResolvedValue(evaluationResult());

    const result = await evaluateAgentState(state);

    const request = evaluateMock.mock.calls[0]?.[0];
    expect(request?.maxRetries).toBe(0);
    expect(JEV_EVALUATION_MAX_RETRIES).toBe(1);
    expect(request?.abortSignal).toBeInstanceOf(AbortSignal);
    expect(request?.providerOptions).toEqual({ gateway: { zeroDataRetention: false } });
    expect(result.assessment.nextAction.confidence).toBe(0.73);
  });

  it('rejects malformed TypeSafe confidence metadata', async () => {
    evaluateMock.mockResolvedValue(
      evaluationResult({ typesafe: { confidence: { nextAction: '0.73' } } }),
    );

    await expect(evaluateAgentState(state)).rejects.toMatchObject({
      code: 'invalid_response',
      message: 'Decision provider returned invalid provider metadata.',
    });
  });

  it('rethrows provider failures as safe local errors', async () => {
    evaluateMock.mockRejectedValue(apiError(429));

    await expect(evaluateAgentState(state)).rejects.toMatchObject({
      code: 'rate_limit',
      message: 'Gateway rate limit reached. Wait before retrying the evaluation.',
    });
  });

  it('bounds state before sending it to Jev', () => {
    const oversizedState: AgentState = {
      ...state,
      task: 't'.repeat(MAX_TASK_LENGTH + 1),
      currentGoal: 'g'.repeat(MAX_TASK_LENGTH + 1),
      repo: {
        ...state.repo,
        scripts: Array.from({ length: MAX_EVALUATION_LIST_ITEMS + 1 }, () => 's'.repeat(3_000)),
        validationScripts: Array.from(
          { length: MAX_EVALUATION_LIST_ITEMS + 1 },
          () => 'v'.repeat(3_000),
        ),
        gitStatus: Array.from({ length: MAX_EVALUATION_LIST_ITEMS + 1 }, () => 'g'.repeat(3_000)),
      },
      observations: Array.from({ length: MAX_EVALUATION_LIST_ITEMS + 1 }, () => 'o'.repeat(3_000)),
      commandsRun: Array.from({ length: MAX_EVALUATION_COMMANDS + 1 }, () => ({
        command: 'c'.repeat(3_000),
        exitCode: 1,
        output: 'o'.repeat(MAX_EVALUATION_COMMAND_OUTPUT_LENGTH + 1),
      })),
    };

    const requestState = boundAgentStateForEvaluation(oversizedState);

    expect(requestState.task).toHaveLength(MAX_TASK_LENGTH);
    expect(requestState.repo.scripts).toHaveLength(MAX_EVALUATION_LIST_ITEMS);
    expect(requestState.observations).toHaveLength(MAX_EVALUATION_LIST_ITEMS);
    expect(requestState.commandsRun).toHaveLength(MAX_EVALUATION_COMMANDS);
    expect(requestState.commandsRun[0]?.output).toHaveLength(MAX_EVALUATION_COMMAND_OUTPUT_LENGTH);
  });
});

describe('normalizeJevEvaluationError', () => {
  it.each([
    [apiError(401), 'authentication'],
    [apiError(429), 'rate_limit'],
    [apiError(404), 'model_unavailable'],
    [apiError(503), 'service_unavailable'],
    [
      new NoSuchModelError({ modelId: 'typesafe-ai/missing', modelType: 'evaluationModel' }),
      'model_unavailable',
    ],
    [new InvalidResponseDataError({ data: { task: 'private task details' } }), 'invalid_response'],
    [new DOMException('timed out', 'TimeoutError'), 'timeout'],
  ] as const)('maps %s to %s without exposing upstream details', (error, code) => {
    const normalized = normalizeJevEvaluationError(error);

    expect(normalized).toBeInstanceOf(JevEvaluationError);
    expect(normalized.code).toBe(code);
    expect(normalized.message).not.toContain('secret');
    expect(normalized.message).not.toContain('private task');
  });

  it('uses the final retry failure to classify a transient request', () => {
    const normalized = normalizeJevEvaluationError(
      new RetryError({
        message: 'retry request body with secret value',
        reason: 'maxRetriesExceeded',
        errors: [apiError(429)],
      }),
    );

    expect(normalized.code).toBe('rate_limit');
  });

  it('uses a safe fallback for unrecognized failures', () => {
    const normalized = normalizeJevEvaluationError(new Error('token=secret-value'));

    expect(normalized.code).toBe('request_failed');
    expect(normalized.message).not.toContain('secret-value');
  });

  it('reports the configured deadline', () => {
    expect(normalizeJevEvaluationError(new DOMException('', 'TimeoutError')).message).toContain(
      `${JEV_EVALUATION_TIMEOUT_MS / 1000} seconds`,
    );
  });
});


describe('Jev user cancellation', () => {
  it('does not invoke the provider when already aborted', async () => {
    vi.mocked(evaluate).mockClear();
    const controller = new AbortController();
    controller.abort('secret reason');
    await expect(evaluateAgentState(state, undefined, { signal: controller.signal })).rejects.toThrow('Run interrupted.');
    expect(evaluate).not.toHaveBeenCalled();
  });

  it('aborts pending evaluation without normalizing it as a timeout or exposing provider errors', async () => {
    const controller = new AbortController();
    let rejectProvider!: (reason: unknown) => void;
    vi.mocked(evaluate).mockReturnValueOnce(new Promise((_resolve, reject) => { rejectProvider = reject; }) as ReturnType<typeof evaluate>);
    const running = evaluateAgentState(state, undefined, { signal: controller.signal });
    await new Promise((resolve) => setImmediate(resolve));
    const invocation = vi.mocked(evaluate).mock.calls.at(-1)?.[0];
    expect(invocation?.abortSignal?.aborted).toBe(false);
    controller.abort('secret reason');
    await expect(running).rejects.toThrow('Run interrupted.');
    expect(invocation?.abortSignal?.aborted).toBe(true);
    rejectProvider(new Error('provider credential details'));
    await new Promise((resolve) => setImmediate(resolve));
  });
});

